#ifndef TRANSLIT_H
#define TRANSLIT_H
// Romanisation for characters Palm Latin can't show (used by CardDav::toPalmLatin):
//  - Chinese ideographs -> pinyin without tones, "Bei Jing" (each syllable capitalised, a space
//    before it; the most customary reading, so 重庆 is "Zhong Qing", not "Chong Qing");
//  - Japanese kana -> Hepburn romaji ("sakura", sokuon doubles, "kya", "-" long mark repeats the vowel);
//    kanji get their Chinese pinyin reading;
//  - Korean Hangul -> Revised Romanization, syllable by syllable ("hangukeo", no liaison).
// Tables: translit_data.cpp (generated by tools/gen_translit.py).
#include <stdint.h>
#include <string>
#include <vector>

// If cps[i] starts a character this module romanises, append it to out and return how many code
// points it used (1..3); else return 0 and leave out alone. *han: the last thing appended was a
// pinyin syllable (so the caller can put a space before a following Latin letter or digit);
// kept up to date here.
size_t translitAppend(const std::vector<uint32_t> &cps, size_t i, std::string &out, bool *han);
#endif
